    static func certificate(_ base64: String) -> SecCertificate {
        SecCertificateCreateWithData(nil, Data(base64Encoded: base64)! as CFData)!
    }

    /// The leaf's AuthorityKeyIdentifier key id (the root's subject key id), base64url.
    static let leafAuthorityKeyId = "ahK5xQts-JgQ2Fc4YaPk7oVF6b8"
